/**
 * Thin wrapper over the OpenAI GPT-Live session-creation endpoint.
 *
 * Verified against the official docs (2026-10-10): server-side
 * POST https://api.openai.com/v1/live/sessions with
 * { session: { model, instructions, ... }, transport: { type: 'webrtc', sdp } }.
 * The repo's pinned openai@6.x has no client.live; this service uses
 * openai@^7 where client.live.create implements exactly this REST call.
 */
import OpenAI from 'openai';

export interface LiveSessionParams {
  /** SDP offer generated by the browser's RTCPeerConnection. */
  offerSdp: string;
  instructions: string;
  model: string;
  /** Responses delegation block (Layer C). Omitted when delegation is disabled. */
  delegation?: {
    type: 'responses';
    responses: {
      model: string;
      instructions: string;
      tools: unknown[];
      tool_choice: 'auto';
      parallel_tool_calls: boolean;
      max_output_tokens: number;
    };
  };
}

export interface LiveSessionCreated {
  /** Opaque session id, e.g. "live_...". Used for the sideband attach URL. */
  sessionId: string;
  /** SDP answer to hand to the browser's setRemoteDescription. */
  answerSdp: string;
  /** Wall-clock duration of the create call (latency instrumentation). */
  durationMs: number;
}

/** Injectable so tests can assert the exact request shape without HTTP. */
export type CreateSessionFn = (params: {
  session: { model: string; instructions: string };
  transport: { type: 'webrtc'; sdp: string };
  delegation?: LiveSessionParams['delegation'];
}) => Promise<{ session: { id: string }; transport: { sdp: string } }>;

export class LiveApiError extends Error {
  readonly status?: number;
  /** True when a retry might succeed (429 / 5xx / network). */
  readonly retryable: boolean;

  constructor(message: string, opts: { status?: number; retryable: boolean }) {
    super(message);
    this.name = 'LiveApiError';
    this.status = opts.status;
    this.retryable = opts.retryable;
  }
}

function defaultCreateFn(apiKey: string): CreateSessionFn {
  const client = new OpenAI({ apiKey });
  return (params) => client.live.create(params);
}

export class LiveSessionClient {
  private readonly createFn: CreateSessionFn;

  constructor(opts: { apiKey: string; createFn?: CreateSessionFn }) {
    this.createFn = opts.createFn ?? defaultCreateFn(opts.apiKey);
  }

  async createSession(params: LiveSessionParams): Promise<LiveSessionCreated> {
    if (!params.offerSdp || params.offerSdp.length < 50) {
      throw new LiveApiError('SDP offer is missing or implausibly short', {
        retryable: false,
      });
    }
    const started = Date.now();
    let created;
    try {
      created = await this.createFn({
        session: { model: params.model, instructions: params.instructions },
        transport: { type: 'webrtc', sdp: params.offerSdp },
        ...(params.delegation ? { delegation: params.delegation } : {}),
      });
    } catch (err) {
      // A typed LiveApiError (e.g. from a previous mapping layer or an
      // injected createFn) passes through; anything else gets mapped.
      if (err instanceof LiveApiError) throw err;
      throw mapCreateError(err);
    }
    const durationMs = Date.now() - started;
    const sessionId = created?.session?.id;
    const answerSdp = created?.transport?.sdp;
    if (!sessionId || !answerSdp) {
      throw new LiveApiError('OpenAI returned a malformed live-session response', {
        retryable: true,
      });
    }
    return { sessionId, answerSdp, durationMs };
  }
}

function mapCreateError(err: unknown): LiveApiError {
  if (err instanceof OpenAI.APIError) {
    const status = err.status;
    if (status === 401 || status === 403) {
      return new LiveApiError(
        'OpenAI rejected the API key (GPT-Live access required)',
        { status, retryable: false },
      );
    }
    return new LiveApiError(`OpenAI live session creation failed (status ${status ?? 'unknown'})`, {
      status,
      retryable: status === 429 || status === undefined || status >= 500,
    });
  }
  if (err instanceof Error) {
    return new LiveApiError(`Live session creation failed: ${err.message}`, {
      retryable: true,
    });
  }
  return new LiveApiError('Live session creation failed with an unknown error', {
    retryable: true,
  });
}
